INSERT INTO "Quest" ("id", "slug", "name", "tier", "summary", "description", "skillSlug", "durationDays", "kind", "skillReqsJson", "unlockReqsJson", "questReqsJson", "rewardJson", "xpPlanJson", "createdByUser", "sortOrder", "createdAt", "coverImage", "rules", "stakes", "howToWin", "destination", "journeyLabel", "journeyNote", "commitmentLevel", "totalXp", "skillWeightsJson", "wealthCents", "deadline", "dailyWorkMinutes", "dailyWorkTitle") VALUES
(2, 'keep-it-clean', 'Keep it Clean!', 'NOVICE', 'One full week of a pristine room.', 'Vacuum and wipe first. Then keep the room tidy every day for a week while you organize the rest.', 'order', 7, 'JOURNEY', NULL, NULL, NULL, NULL, '{"dayXp":[0],"completionBonus":{"order":800,"hygiene":200}}', 0, 2, 1787001320563, 'pexels-kien-6026720.jpg', 'Daily “Keep it Tidy!” is locked until Vacuum and Wipe is done. Missed days after unlock are recorded. The room must stay pristine for seven days.', 'A messy room bleeds into everything else. This week is the reset.', 'Finish Vacuum and Wipe, check in Keep it Tidy! every day for a week, complete the organize subtasks, then mark the destination.', 'One full week of a pristine room.', 'Keep it Tidy!', 'Daily tidy check-in. Unlocks after Vacuum and Wipe. Expected every day.', 7, 1000, '[{"slug":"order","weight":8},{"slug":"hygiene","weight":2}]', 0, NULL, NULL, NULL),
(5, 'ordo-diei', 'Ordo Diei', 'NOVICE', 'Forge a Consuetudo and walk it once. Unlock Practice.', 'A day without order is a day spent reacting. Name a Consuetudo — a morning practice, an evening close, any sequence you mean to keep — then walk every step from start to finish. One forged practice, one completed walk. After that, Horologium opens Consuetudo as a fourth mode, and you may keep as many routines as the day can hold.', 'strategy', NULL, 'DESTINATION', NULL, NULL, NULL, '{"title":"Consuetudo","features":["feature:consuetudo"]}', '{"dayXp":[0],"completionBonus":{"strategy":1200,"focus":200,"discipline":600}}', 0, 3, 1787087443544, 'pexels-sikunovruslan-20373905.jpg', 'Forge one Consuetudo (name, steps, durations). Complete it once in Horologium. Skips are allowed on the walk; the destination still counts. Until the quest is done you may keep only one routine.', 'Without a practice the morning dissolves. This quest puts the first sequence on the bronze.', 'Create a Consuetudo, then complete it once. The feature unlocks on destination.', 'Complete one Consuetudo from start to finish.', NULL, NULL, 1, 2000, '[{"slug":"strategy","weight":6},{"slug":"focus","weight":1},{"slug":"discipline","weight":3}]', 0, NULL, NULL, NULL),
(6, 'karlskroona-agent', 'Karlskroona Agent', 'NOVICE', 'Making an agent for processing invoices for a fruit/vegetable wholesaler.', 'It is not allowed to publish and send to production something, I am NOT convinced is working nearly ideally.
