INSERT INTO "ScriptoriumWork" ("id", "title", "notes", "icon", "tier", "dueDate", "durationMinutes", "effort", "skillWeightsJson", "status", "questId", "sortOrder", "createdAt", "updatedAt") VALUES
(1, 'Angular Learning', 'Learn Angular + TypeScript for front-end developer role (e-teenuste arendaja). Intensive plan. Day 1: TypeScript, Day 2: Angular Core, Day 3: Build CRUD app.', '🅰️', 'TEMPESTIVA', NULL, 480, 6, '[{"slug":"knowledge","weight":7},{"slug":"focus","weight":3}]', 'OPEN', NULL, 0, 1787529679079, 1787529679079),
(2, 'SEO Dashboard for Clients', 'Kliendile nähtav SEO tulemuste dashboard. Algne idee vaultist.', '📈', 'COGITATA', NULL, NULL, 5, NULL, 'OPEN', NULL, 0, 1787529679107, 1787529679107),
(3, 'Hermes raamatupidamise integratsioon: Merit Aktiv', 'Automatiseeritud raamatupidamise andmevahetus Merit Aktivaga Hermes agentide kaudu.', '📊', 'COGITATA', NULL, NULL, 6, NULL, 'OPEN', NULL, 0, 1787529679139, 1787529679139),
(4, 'Lastelaagrite keskne rakendus', 'Kogub kokku laagripakkujad, allkirjastamine, maksmine jms. Algne plaan: Java + Angular.', '🏕️', 'COGITATA', NULL, NULL, 8, NULL, 'OPEN', NULL, 0, 1787529679177, 1787529679177),
(5, 'Jaak Juskele blogilehe overhaul', 'Paku talle tasuta viisakas blogi + domeen. Tal päriselt huvitav jutt, mida peaksid inimesed nägema!', '✍️', 'COGITATA', NULL, NULL, 3, NULL, 'OPEN', NULL, 0, 1787529679213, 1787591296789),
(6, 'Ridge Capital lehe overhaul', 'Migreerida WordPressist Astro + Cloudflare peale. Hetkel minu tehtud WP, mis võiks olla parem.', '🏢', 'COGITATA', NULL, NULL, 6, NULL, 'OPEN', NULL, 0, 1787529679249, 1787529679249),
(7, 'Blackstack: veebistrateegia + workflows', 'Veebi loomise ja kliendikohtlemise protsessid. Enne alustamist kaardista, mis on hinnastuse sees. Klient soovib customizabilityt — sektsioonide paigutus, värvid.', '🌐', 'TEMPESTIVA', NULL, 480, 7, NULL, 'OPEN', NULL, 0, 1787529679287, 1787529679287),
(9, 'Linux seadistus katkise monitoriga läptopile', 'Linuxi install + seadistus arvutile, kus sisemine ekraan katki — vajab external monitori või remote-setupi.', '💻', 'COGITATA', NULL, 120, 4, NULL, 'OPEN', NULL, 0, 1787529691359, 1787529691359),
(10, 'ladu24.ee SEO meeldetuletus', 'Tuleta ladu24.ee meelde SEO tööde kohta — pakkusin neile SEO teenuseid.', '📋', 'COGITATA', NULL, 30, 2, NULL, 'OPEN', NULL, 0, 1787529691393, 1787529691393),
(11, 'Pangaasjad korda (bank admin)', 'Pangaga seotud admin-asjad. Madal prioriteet, bucket task.', '🏦', 'COGITATA', NULL, 60, 3, NULL, 'OPEN', NULL, 0, 1787529691426, 1787529691426),
(12, 'XP Life RPG — täiendused NoEscapele', 'NoEscape Life RPG edasiarendused: dailies auto-checkin, Scriptorium-põhine questide loomine, habit tracking, Horologium integreering. Vt vault/projects/rpg-productivity-game.md täpsemalt.', '🎮', 'TEMPESTIVA', NULL, 600, 7, '[{"slug":"dev","weight":8},{"slug":"strategy","weight":2}]', 'OPEN', NULL, 0, 1787529691458, 1787529691458),
(14, '🐛 Horologium: pause resets timer to zero', 'When pausing the Consuetudo/Horologium timer, the elapsed time resets to zero instead of preserving the current value. Steps to reproduce: start a routine step timer → press pause → timer shows 0 instead of the accumulated time.', 'bug', 'TEMPESTIVA', NULL, NULL, 3, '[{"slug":"dev","weight":10}]', 'ARCHIVED', NULL, 0, 1787562683522, 1787589337782),
(15, '🐛 Notes modal: overlaps elements + no close button', 'ON MOBILE: When opening notes in Consuetudo horologium (both in scenery and default views), the notes textarea appears on top of other UI elements making it impossible to close. Make sure you fix the mobile view and then verify that desktop doesnt have the same issue.', 'bug', 'TEMPESTIVA', NULL, NULL, 2, '[{"slug":"dev","weight":10}]', 'ARCHIVED', NULL, 0, 1787562683552, 1787591079336),
(17, 'NoEscape arendus', 'Lisada funktsionaalsus: saan sätestada dailyde ja questide subtaskide aega ka ilma seda trackimata. Trackimine teeb automaatselt - kui pole tracked siis pakub võimalust completionil määrata kulunud aega.
